import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"3.0.0-WP06g3 — the real-hardware fix batch (ocse_enc_fix)","description":"","frontmatter":{},"headers":[],"relativePath":"release/3.0.0-WP06g3.md","filePath":"release/3.0.0-WP06g3.md"}'),s={name:"release/3.0.0-WP06g3.md"};function n(i,e,d,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="_3-0-0-wp06g3-—-the-real-hardware-fix-batch-ocse-enc-fix" tabindex="-1">3.0.0-WP06g3 — the real-hardware fix batch (ocse_enc_fix) <a class="header-anchor" href="#_3-0-0-wp06g3-—-the-real-hardware-fix-batch-ocse-enc-fix" aria-label="Permalink to &quot;3.0.0-WP06g3 — the real-hardware fix batch (ocse_enc_fix)&quot;">​</a></h1><p>The postmortem batch: seven real-machine disasters from the WP06g2 field test, root-caused byte-by-byte and fixed. Plus the recovery environment on every path, and the original g3 goal (the OCSE/OCIRE encoding repair).</p><h2 id="what-changed" tabindex="-1">What changed <a class="header-anchor" href="#what-changed" aria-label="Permalink to &quot;What changed&quot;">​</a></h2><ul><li><strong>Disk probing matches real PCs (4.1).</strong> The AHCI probe no longer matches a single exact PCI class code: RAID/RST-mode SATA controllers (class 0x0104, the factory default on many brand machines) are visible now, alongside the classic 0x010601. NVMe gained timeout retries and a disable-CC rewrite on the real-hardware tolerance path. And the probe is no longer a black box: every AHCI and NVMe controller event logs to the <strong>serial line</strong> (the q35+AHCI battery shows 8 <code>ahci:</code> lines on serial where the old kernel showed zero).</li><li><strong><code>serial_encoding utf8|gbk</code> (4.2).</strong> The kernel serial output is UTF-8 by default and converts to GBK on demand - Chinese serial tools (GBK by convention) render <code>lang zh</code> cleanly now. OCSE&#39;s <code>ocse_out</code> rides the same standard (one policy, not two).</li><li><strong>The VMware boot crash (4.3).</strong> The OCBL real-mode stack tops at 0x8E000 now (below every observed EBDA), and the boot-state monitor reads the BDA 0x40E EBDA base and disables its state area when a large EBDA would overlap it. Awaits the user&#39;s real-machine confirmation.</li><li><strong>OCIRE on every path (4.4).</strong> The main ISO carries <code>/boot/ocire.elf</code>; the OCBL menu scans and lists &quot;OCIRE recovery&quot;; the installer writes a <strong>dedicated recovery partition</strong> (a fresh carve from the disk&#39;s unallocated tail, FAT32, with the recovery kernel streamed onto it - the streamed copy landed this batch after the zh font growth exposed the fixed-buffer read). The installed disk boots with both entries.</li><li><strong>The editors are actually localized (4.5).</strong> The 21 hardcoded English UI strings in the shared editor core route through <code>tr_()</code>; the nano legend, prompts and shortcuts are Chinese under <code>lang zh</code>.</li><li><strong>A real IME preedit buffer (4.6).</strong> Pinyin never enters the text: it composes in a preedit strip rendered on the status bar (with the candidates and the IME state), and a failed IME service call reports instead of silently passing letters into the file.</li><li><strong>Differential rendering (4.7).</strong> The nano bar pins to the last row via ANSI positioning and repaints only what changed: the measured keystroke stream carries <strong>zero</strong> newlines per letter (the postmortem measured 3 scrolled lines per keystroke, 8 full-bar prints per session).</li><li><strong>OCSE/OCIRE encoding repair (4.8, the original g3 goal).</strong> The em-dash mapping (GB2312 0xA1AA vs U+2014) that broke whole-string conversion is fixed on both the OCSE tables and the main-kernel font blob; OCIRE gained the hanzi font, UTF-8 decode and the zh strings (its &quot;mojibake&quot; was missing capability). The zh-capable ocire.elf is 6x larger - see the streaming installer fix above.</li><li><strong>Tooling (4.9).</strong> The release boot gates match the live serial banners again; the &quot;branches: ain]&quot; CI-workflow leftover turned out to be a terminal-transcription phantom (a literal <code>[m</code> eaten as an ANSI reset) - audited byte-level, retired from KNOWN_ISSUES.</li><li><strong>Kernel-window diet.</strong> The nine ~16-18 KiB static TLS record buffers moved to the heap (the identity window had closed to 24 KiB; the CI&#39;s gcc-13 crossed it). HTTPS e2e 7/7 on the dieted kernel.</li></ul><h2 id="assets-sha256" tabindex="-1">Assets (SHA256) <a class="header-anchor" href="#assets-sha256" aria-label="Permalink to &quot;Assets (SHA256)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Asset</th><th>Size</th><th>SHA256</th></tr></thead><tbody><tr><td>opencube-3.0.0-WP06g3.iso</td><td>4210688</td><td>34bcccdbcf8f66ab9e70bcb8c9a516a4a491d28c3dd9b47d970ee1b37c93fef9</td></tr><tr><td>ocse-3.0.0-WP06g3.iso</td><td>5038080</td><td>0abb622cf3e88641db227fcec1082ecdfa42c367d6eb85247524e4a3923cf3ff</td></tr><tr><td>OpenCubeOS-src-3.0.0-WP06g3.zip</td><td>6106241</td><td>bb533f9f058844eee7baf9fefa794158fed2802fad9eeaf99cddbb13bc8b9297</td></tr><tr><td>OpenCubeOS-3.0.0-WP06g3-update.tar.gz</td><td>1411653</td><td>76f1e35a11204befe4396c1b17377a2c19c298d8f9200cecee27891e6ec10fd0</td></tr></tbody></table><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;Evidence&quot;">​</a></h2><p><code>evidence/3_0_0_wp06g3_ocse_enc_fix/</code> - the postmortem reproductions (serial byte dumps, screendumps) and the per-fix battery logs (disk-probe serial, encoding byte streams, install E2E with the carved recovery partition, editor rework stream + screens, OCIRE zh).</p>',8)])])}const f=t(s,[["render",n]]);export{g as __pageData,f as default};
